-- ---------- derived history (INSERT ... SELECT from the seeded rows; ids = kind 08xx + entity serial * 10 + audience) ----------
-- audience slots: 1 first role, 2 second role, 3 third role, 5 district, 6 state, 7 zonal, 8 central console

-- booking -> doctor
INSERT INTO engage.event (id, type, from_role, created_by_user_id, to_roles, to_user_id, title, text, href, entity_type, entity_id, patient_person_id, hospital_id, pharmacy_id, district_id, created_at)
SELECT util.seed_uuid(802, (right(a.id::text, 12)::bigint + (CASE substr(a.id::text, 10, 4) WHEN '0203' THEN 100 ELSE 0 END)) * 10 + 1),
       'booking',
       'citizen',
       (SELECT cu.id FROM identity.app_user cu WHERE cu.person_id = a.citizen_person_id AND cu.account_type = 'citizen' ORDER BY cu.created_at LIMIT 1),
       ARRAY['doctor']::engage.event_role[],
       NULL,
       'New booking · ' || p.full_name,
       to_char(lower(sl.during) AT TIME ZONE 'Asia/Kolkata', 'Dy DD Mon, HH24:MI') || ' · ' || replace(a.visit_type, '_', '-') || ' · token ' || a.token_no || ' · ' || a.booking_ref,
       '/doctor?section=schedule',
       'engage.appointment',
       a.id,
       a.citizen_person_id,
       sl.hospital_id,
       NULL,
       NULL,
       a.requested_at
FROM engage.appointment a JOIN engage.appointment_slot sl ON sl.id = a.slot_id JOIN identity.person p ON p.id = a.citizen_person_id
WHERE a.status = 'confirmed' AND a.id <> 'cfd00000-0141-4000-8000-000000000004' AND (a.id::text LIKE 'cfd00000-0141-%' OR a.id::text LIKE 'cfd00000-0203-%')
ON CONFLICT (id) DO NOTHING;

-- booking -> hospitaladmin
INSERT INTO engage.event (id, type, from_role, created_by_user_id, to_roles, to_user_id, title, text, href, entity_type, entity_id, patient_person_id, hospital_id, pharmacy_id, district_id, created_at)
SELECT util.seed_uuid(802, (right(a.id::text, 12)::bigint + (CASE substr(a.id::text, 10, 4) WHEN '0203' THEN 100 ELSE 0 END)) * 10 + 2),
       'booking',
       'citizen',
       (SELECT cu.id FROM identity.app_user cu WHERE cu.person_id = a.citizen_person_id AND cu.account_type = 'citizen' ORDER BY cu.created_at LIMIT 1),
       ARRAY['hospitaladmin']::engage.event_role[],
       NULL,
       'New booking · ' || p.full_name,
       to_char(lower(sl.during) AT TIME ZONE 'Asia/Kolkata', 'Dy DD Mon, HH24:MI') || ' · ' || replace(a.visit_type, '_', '-') || ' · token ' || a.token_no || ' · ' || a.booking_ref,
       '/hospital-admin?section=overview',
       'engage.appointment',
       a.id,
       a.citizen_person_id,
       sl.hospital_id,
       NULL,
       NULL,
       a.requested_at
FROM engage.appointment a JOIN engage.appointment_slot sl ON sl.id = a.slot_id JOIN identity.person p ON p.id = a.citizen_person_id
WHERE a.status = 'confirmed' AND a.id <> 'cfd00000-0141-4000-8000-000000000004' AND (a.id::text LIKE 'cfd00000-0141-%' OR a.id::text LIKE 'cfd00000-0203-%')
ON CONFLICT (id) DO NOTHING;

