       NULL,
       'e-Signed prescription · ' || pat.full_name,
       COALESCE(it.txt, 'e-prescription') || ' · ' || (SELECT pp.full_name FROM identity.app_user uu JOIN identity.person pp ON pp.id = uu.person_id WHERE uu.id = p.doctor_user_id) || ' · ' || p.rx_number,
       '/pharmacist?section=queue',
       'pharmacy.prescription',
       p.id,
       p.patient_person_id,
       p.hospital_id,
       COALESCE(f.pharmacy_id, (SELECT d.pharmacy_id FROM pharmacy.prescription_delivery d WHERE d.prescription_id = p.id LIMIT 1)),
       NULL,
       p.issued_at + interval '1 minute'
FROM pharmacy.prescription p JOIN identity.person pat ON pat.id = p.patient_person_id
LEFT JOIN pharmacy.rx_fulfilment f ON f.prescription_id = p.id
LEFT JOIN LATERAL (SELECT string_agg(m.generic_name || ' ×' || trim_scale(i.quantity)::text, ', ' ORDER BY i.id) AS txt
                     FROM pharmacy.prescription_item i JOIN pharmacy.medicine m ON m.id = i.medicine_id WHERE i.prescription_id = p.id) it ON true
WHERE p.id <> 'cfd00000-0211-4000-8000-000000000001' AND p.status <> 'cancelled' AND p.issued_at >= '2026-09-01+05:30' AND COALESCE(f.pharmacy_id, (SELECT d.pharmacy_id FROM pharmacy.prescription_delivery d WHERE d.prescription_id = p.id LIMIT 1)) IS NOT NULL
ON CONFLICT (id) DO NOTHING;

