FROM inpatient.escalation x JOIN identity.person pat ON pat.id = x.patient_person_id JOIN access.admission ad ON ad.id = x.admission_id
JOIN org.bed bd ON bd.id = ad.bed_id
WHERE x.id <> 'cfd00000-0233-4000-8000-000000000012' AND x.paged_at >= '2026-10-17+05:30' AND x.news_score >= 5
ON CONFLICT (id) DO NOTHING;

-- dispensed -> citizen
INSERT INTO engage.event (id, type, from_role, created_by_user_id, to_roles, to_user_id, title, text, href, entity_type, entity_id, patient_person_id, hospital_id, pharmacy_id, district_id, created_at)
SELECT util.seed_uuid(811, (right(p.id::text, 12)::bigint + (CASE substr(p.id::text, 10, 4) WHEN '0415' THEN 100 ELSE 0 END)) * 10 + 1),
       'dispensed',
       'pharmacist',
       f.verified_by_user_id,
       ARRAY['citizen']::engage.event_role[],
       NULL,
       'Ready to collect · ' || ph.name,
