-- ---------- read state: each demo persona has read everything older than the cutoff (the feed shows only 'today' as unread) ----------
-- Visibility is decided by the real function engage.event_visible under a temporary request context (transaction-local settings).
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      (1, 'citizen',        '2026-10-17 00:00:00+05:30'::timestamptz),
      (2, 'doctor', '2026-10-17 06:00:00+05:30'::timestamptz),
      (3, 'staff', '2026-10-17 06:00:00+05:30'::timestamptz),
      (4, 'staff', '2026-10-17 06:00:00+05:30'::timestamptz),
      (5, 'staff', '2026-10-17 06:00:00+05:30'::timestamptz),
      (6, 'pharmacist', '2026-10-17 06:00:00+05:30'::timestamptz),
      (7, 'pharmacy_admin', '2026-10-17 06:00:00+05:30'::timestamptz),
      (8, 'hospital_admin', '2026-10-17 06:00:00+05:30'::timestamptz),
      (9, 'district_admin', '2026-10-17 06:00:00+05:30'::timestamptz)
    ) AS v(serial, acct, cutoff) LOOP
    PERFORM set_config('app.user_id', util.seed_uuid(2, r.serial)::text, true);
    PERFORM set_config('app.person_id', util.seed_uuid(1, r.serial)::text, true);
    PERFORM set_config('app.account_type', r.acct, true);
    INSERT INTO engage.event_read (event_id, user_id, read_at)
    SELECT e.id, util.seed_uuid(2, r.serial), e.created_at + interval '30 minutes'
      FROM engage.event e
     WHERE e.id::text LIKE 'cfd00000-08%'
       AND e.created_at < r.cutoff
       AND engage.event_role_of(util.seed_uuid(2, r.serial)) = ANY (e.to_roles)
       AND engage.event_visible(e.to_roles, e.created_by_user_id, e.to_user_id, e.patient_person_id, e.hospital_id, e.pharmacy_id,
                                e.district_id, e.state_id, e.zone_id)
    ON CONFLICT DO NOTHING;
  END LOOP;
  -- Anjali also read the two blood requests of today (so her bell shows 3 unread: lab result, prescription, ready to collect, like the design)
  INSERT INTO engage.event_read (event_id, user_id, read_at) VALUES ('cfd00000-0801-4000-8000-000000000101', 'cfd00000-0002-4000-8000-000000000001', '2026-10-17 14:40:00+05:30'),
    ('cfd00000-0813-4000-8000-000000000011', 'cfd00000-0002-4000-8000-000000000001', '2026-10-17 11:40:00+05:30') ON CONFLICT DO NOTHING;   -- 813-11 = the Kottayam request of 11:20
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.person_id', '', true);
  PERFORM set_config('app.account_type', '', true);
END $$;

-- ---------- citizen 'My care' notifications (engage.notification, channel in_app) that deliver Anjali's care events ----------
-- id = cfd00000-0816-...: serial = (event kind - 800) * 1000000 + event serial. event_id links the delivery to the event.
INSERT INTO engage.notification (id, user_id, channel, template_code, payload, status, created_at, sent_at, event_id, kind, priority)
SELECT util.seed_uuid(816, (substr(e.id::text, 10, 4)::int - 800) * 1000000 + right(e.id::text, 12)::bigint),
       'cfd00000-0002-4000-8000-000000000001', 'in_app',
       CASE e.type::text WHEN 'booking' THEN 'appointment_confirmed' WHEN 'prescription' THEN 'rx_signed' WHEN 'dispensed' THEN 'rx_ready'
                         WHEN 'collected' THEN 'rx_collected' WHEN 'lab-result' THEN 'lab_result_ready' WHEN 'imaging-result' THEN 'imaging_result_ready'
                         WHEN 'break-glass' THEN 'record_opened' ELSE 'blood_request' END,
       jsonb_build_object('title', e.title, 'body', e.text, 'action', jsonb_build_object('href', e.href,
            'label', CASE e.type::text WHEN 'dispensed' THEN 'See in Medicines' WHEN 'prescription' THEN 'Track at pharmacy' WHEN 'lab-result' THEN 'See in Documents'
                                       WHEN 'break-glass' THEN 'See access history' ELSE 'View' END)),
       'delivered', e.created_at, e.created_at + interval '1 minute', e.id, 'my_care',
       CASE WHEN e.type::text IN ('break-glass', 'blood-request') THEN 'high' ELSE 'normal' END
  FROM engage.event e
WHERE 'citizen' = ANY (e.to_roles) AND e.patient_person_id = 'cfd00000-0001-4000-8000-000000000001' AND e.id::text LIKE 'cfd00000-08%'
   AND e.type::text IN ('booking', 'prescription', 'dispensed', 'collected', 'lab-result', 'imaging-result', 'break-glass')
   AND e.created_at >= '2026-10-01+05:30'
ON CONFLICT DO NOTHING;
-- the blood request is a broadcast (no patient), so it is added on its own
INSERT INTO engage.notification (id, user_id, channel, template_code, payload, status, created_at, sent_at, event_id, kind, priority)
SELECT util.seed_uuid(816, 1 * 1000000 + 101), 'cfd00000-0002-4000-8000-000000000001', 'in_app', 'blood_request',
       jsonb_build_object('title', e.title, 'body', e.text, 'action', jsonb_build_object('href', e.href, 'label', 'See in Blood donation')),
       'delivered', e.created_at, e.created_at + interval '1 minute', e.id, 'my_care', 'high'
  FROM engage.event e WHERE e.id = 'cfd00000-0801-4000-8000-000000000101'
ON CONFLICT DO NOTHING;

-- ---------- audit.activity_log rows for the access sessions that have none (10_, 20_, 50_ sessions) ----------
-- The hash chain is built by the trigger audit.chain_row (stream 33 = Kerala). The rows are appended in session-time order; idempotency is
-- by details->>'seed_key'. Scope columns and the hashed copy details.scope.hospital carry the same hospital (audit.check_scope_columns stays NULL).
-- Key / card sessions use the action 'access.session_open' (the citizen already reads them from access.v_access_history; the action does not match
-- the order-access view). Admission sessions: 'admission.open'. Break-glass: 'breakglass.open' (shown to the patient). Session 0510-2 is skipped:
-- 50_ has the audit row h-audit-3 for it.
INSERT INTO audit.activity_log (stream_id, occurred_at, user_id, account_type, action, entity_type, entity_id, patient_person_id, session_id, hospital_id, details)
SELECT 33, s.started_at, s.user_id, u.account_type, CASE s.mode::text WHEN 'break_glass' THEN 'breakglass.open' WHEN 'admission' THEN 'admission.open' ELSE 'access.session_open' END, 'access_session', s.id, s.patient_person_id, s.id, h.hid,
       jsonb_build_object('seed_key', 'access:open:' || s.id, 'summary', CASE s.mode::text WHEN 'break_glass' THEN 'Break-glass session opened' WHEN 'admission' THEN 'Admission-mode session opened'
         ELSE 'Citizen key session opened · 30 min' END,
                          'scope', jsonb_build_object('hospital', h.hid))
FROM access.access_session s
JOIN identity.app_user u ON u.id = s.user_id
LEFT JOIN identity.doctor_profile dp ON dp.user_id = s.user_id
LEFT JOIN identity.staff_profile sp ON sp.user_id = s.user_id
CROSS JOIN LATERAL (SELECT COALESCE((SELECT ph.hospital_id FROM identity.doctor_posting_history ph
                                      WHERE ph.user_id = s.user_id AND ph.valid @> s.started_at), dp.hospital_id, sp.hospital_id) AS hid) h
WHERE (s.id::text LIKE 'cfd00000-0104-%' OR s.id::text LIKE 'cfd00000-0201-%' OR s.id::text LIKE 'cfd00000-0510-%')
  AND s.id <> 'cfd00000-0510-4000-8000-000000000002'
  AND NOT EXISTS (SELECT 1 FROM audit.activity_log l WHERE l.details ->> 'seed_key' = 'access:open:' || s.id)
ORDER BY s.started_at, s.id;
INSERT INTO audit.activity_log (stream_id, occurred_at, user_id, account_type, action, entity_type, entity_id, patient_person_id, session_id, hospital_id, details)
SELECT 33, s.ended_at, s.user_id, u.account_type, 'access.session_end', 'access_session', s.id, s.patient_person_id, s.id, h.hid,
       jsonb_build_object('seed_key', 'access:end:' || s.id, 'summary', 'Session ended · ' || COALESCE(s.ended_by::text, 'timeout'),
                          'scope', jsonb_build_object('hospital', h.hid))
FROM access.access_session s
JOIN identity.app_user u ON u.id = s.user_id
LEFT JOIN identity.doctor_profile dp ON dp.user_id = s.user_id
LEFT JOIN identity.staff_profile sp ON sp.user_id = s.user_id
CROSS JOIN LATERAL (SELECT COALESCE((SELECT ph.hospital_id FROM identity.doctor_posting_history ph
                                      WHERE ph.user_id = s.user_id AND ph.valid @> s.started_at), dp.hospital_id, sp.hospital_id) AS hid) h
WHERE (s.id::text LIKE 'cfd00000-0104-%' OR s.id::text LIKE 'cfd00000-0201-%' OR s.id::text LIKE 'cfd00000-0510-%')
  AND s.id <> 'cfd00000-0510-4000-8000-000000000002'
  AND s.ended_at IS NOT NULL AND s.mode::text <> 'break_glass'
  AND NOT EXISTS (SELECT 1 FROM audit.activity_log l WHERE l.details ->> 'seed_key' = 'access:end:' || s.id)
ORDER BY s.ended_at, s.id;

-- keep the booking-reference sequence ahead of the seeded refs (also done by migration 129; GREATEST makes it a no-op on a re-run)
SELECT setval('engage.booking_ref_seq', GREATEST((SELECT last_value FROM engage.booking_ref_seq),
  (SELECT coalesce(max(substring(booking_ref FROM '[0-9]+$')::bigint), 0) FROM engage.appointment WHERE booking_ref ~ '^DEMO-APT-[0-9]+$'), 59100));

COMMIT;
